// ─── File: src/main/java/com/bank/kyc/model/Account.java ───
// One entity spanning TWO tables sharing the primary key account_id
package com.bank.kyc.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "accounts")                                   // PRIMARY table
@SecondaryTable(
    name = "account_kyc",                                   // SECONDARY table
    pkJoinColumns = @PrimaryKeyJoinColumn(name = "account_id")  // joined on shared PK
)
public class Account {

    @Id
    @Column(name = "account_id")
    private String accountId;                               // PK present in BOTH tables

    // default table = primary (accounts)
    @Column(name = "holder_name", nullable = false)
    private String holderName;

    @Column(name = "balance", nullable = false, precision = 15, scale = 2)
    private BigDecimal balance;

    // routed to the SECONDARY table (account_kyc)
    @Column(table = "account_kyc", name = "pan", nullable = false, length = 10)
    private String pan;

    @Column(table = "account_kyc", name = "aadhaar_doc", columnDefinition = "TEXT")
    private String aadhaarDoc;

    protected Account() {}

    public Account(String accountId, String holderName, BigDecimal balance, String pan, String aadhaarDoc) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
        this.pan = pan;
        this.aadhaarDoc = aadhaarDoc;
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public String getPan() { return pan; }
    public String getAadhaarDoc() { return aadhaarDoc; }
}
