// ─── File: src/main/java/com/bank/kyc/service/AccountKycService.java ───
package com.bank.kyc.service;

import com.bank.kyc.dto.AccountKycView;
import com.bank.kyc.model.Account;
import com.bank.kyc.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class AccountKycService {

    private final AccountRepository accountRepo;

    @Transactional
    public AccountKycView open(String accountId, String holderName, BigDecimal balance,
                                String pan, String aadhaarDoc) {
        Account account = new Account(accountId, holderName, balance, pan, aadhaarDoc);
        accountRepo.save(account);
        // Hibernate issues TWO inserts:
        //   INSERT INTO accounts (account_id, holder_name, balance) VALUES (...)
        //   INSERT INTO account_kyc (account_id, pan, aadhaar_doc) VALUES (...)
        log.info("Opened {} — common cols → accounts, KYC cols → account_kyc (one entity, two tables)", accountId);
        return AccountKycView.from(account);
    }

    @Transactional(readOnly = true)
    public AccountKycView view(String accountId) {
        Account account = accountRepo.findById(accountId).orElseThrow();
        // Hibernate JOINed accounts + account_kyc on account_id to assemble ONE entity
        log.info("Loaded {} — assembled from accounts JOIN account_kyc (pan from secondary table)", accountId);
        return AccountKycView.from(account);
    }
}
