// ─── File: src/test/java/com/bank/kyc/model/SecondaryTableTest.java ───
package com.bank.kyc.model;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import jakarta.persistence.Column;
import jakarta.persistence.SecondaryTable;
import jakarta.persistence.Table;
import static org.assertj.core.api.Assertions.*;

class SecondaryTableTest {

    @Test
    void entityDeclaresPrimaryAndSecondaryTables() {
        Table t = Account.class.getAnnotation(Table.class);
        SecondaryTable st = Account.class.getAnnotation(SecondaryTable.class);
        assertThat(t.name()).isEqualTo("accounts");
        assertThat(st.name()).isEqualTo("account_kyc");
    }

    @Test
    void panIsRoutedToSecondaryTable() throws Exception {
        Field pan = Account.class.getDeclaredField("pan");
        Column c = pan.getAnnotation(Column.class);
        assertThat(c.table()).isEqualTo("account_kyc"); // routed to secondary table
    }

    @Test
    void holderNameStaysInPrimaryTable() throws Exception {
        Field holderName = Account.class.getDeclaredField("holderName");
        Column c = holderName.getAnnotation(Column.class);
        assertThat(c.table()).isEmpty(); // default → primary table
    }

    @Test
    void secondaryTableJoinsOnPrimaryKey() {
        SecondaryTable st = Account.class.getAnnotation(SecondaryTable.class);
        assertThat(st.pkJoinColumns()[0].name()).isEqualTo("account_id"); // shared PK join
    }
}
